    c=S.env.robots[0].part_controllers['right']

def ee(): return S.data.site_xpos[sid].copy()
def ori(): return S.data.site_xmat[sid].reshape(3,3).copy()
def obj(): return S.data.xpos[S.model.body('obj_main').id].copy()
def body(n): return S.data.xpos[S.model.body(n).id].copy()
def snap(name):
    Image.fromarray(S.render_grid()).save('/app/output/'+name+'.png')
def info():
    print('step',len(S.actions),'ee',ee(),'obj',obj(),'base',body('mobilebase0_base'),'torso',S.data.qpos[3],'success',S.check(),flush=True)
def down(theta):
    x=np.array([np.cos(theta),np.sin(theta),0]); z=np.array([0.,0.,-1.]); return np.column_stack([x,np.cross(z,x),z])
def tick(p=None,o=None,grip=-1,base=None,torso=0,mode=-1,vel=.4):
    a=np.zeros(12); a[6]=grip;a[10]=torso;a[11]=mode
    if p is not None:
        error=np.asarray(p)-ee()
        a[:3]=np.clip(c.origin_ori.T@error/.05,-vel,vel)
    if o is not None:
        err=R.from_matrix(np.asarray(o)@ori().T).as_rotvec()
        a[3:6]=np.clip(c.origin_ori.T@err/.5,-.4,.4)
    if base is not None: a[7:10]=base
    return S.step(a)
def move(p,o=None,grip=-1,n=160,tol=.008,vel=.4):
    p=np.asarray(p)
    for i in range(n):
        tick(p,o,grip=grip,vel=vel)
        if np.linalg.norm(p-ee())<tol and (o is None or np.linalg.norm(R.from_matrix(o@ori().T).as_rotvec())<.04):
            break
    print('MOVE',i+1,'error',p-ee(),flush=True);info()
def wait(n=20,grip=-1,p=None,o=None):
    for _ in range(n): tick(p,o,grip=grip)
def base_to(xy,n=140):
    target=np.asarray(xy)
    for i in range(n):
        bp=body('mobilebase0_base')
        rb=S.data.xmat[S.model.body('mobilebase0_base').id].reshape(3,3)
        v=rb.T@np.r_[2*(target-bp[:2]),0]
        tick(base=np.r_[np.clip(v[:2],-.35,.35),0],mode=1)
        if np.linalg.norm(target-body('mobilebase0_base')[:2])<.007: break
    for _ in range(10):tick(mode=1)
    print('BASE',i+1,flush=True);info()
def contacts(prefix='obj_'):
    out=[]
    for ct in S.data.contact:
        n1=S.model.geom(ct.geom1).name;n2=S.model.geom(ct.geom2).name
        if n1.startswith(prefix) or n2.startswith(prefix):out.append((n1,n2,ct.dist))
    print(out,flush=True)
